import { Preferences } from '@capacitor/preferences';

// ---------------------------------------------------------------------------
// Namespaced settings manager built on top of @capacitor/preferences.
// ---------------------------------------------------------------------------

// Delimiter used to encode the namespace into each Preferences storage key.
// Including the delimiter in the prefix used for filtering makes the matching
// delimiter-aware: the namespace `app` (prefix `app::`) will never match keys
// belonging to the namespace `appearance` (whose keys look like `appearance::...`).
const DELIMITER = '::';

// Fixed namespace schemas. Each entry maps a setting key to its typed default
// value. The JavaScript type of the default is preserved across persistence by
// serializing values with JSON on the way in and parsing them on the way out.
const SCHEMAS = {
  app: {
    theme: 'light', // string
    fontSize: 14, // number
    notifications: true, // boolean
  },
  appearance: {
    theme: 'system', // string
    accent: 'blue', // string
  },
  editor: {
    tabSize: 4, // number
    wordWrap: false, // boolean
  },
};

/**
 * Build the Preferences storage key for a (namespace, settingKey) pair.
 */
const storageKey = (namespace, key) => `${namespace}${DELIMITER}${key}`;

/**
 * The prefix every stored key for a given namespace shares. Used for
 * delimiter-aware filtering of the Preferences `keys()` listing.
 */
const namespacePrefix = (namespace) => `${namespace}${DELIMITER}`;

/**
 * Reject the promise if `namespace` is not a known namespace.
 */
function assertNamespace(namespace) {
  if (!Object.prototype.hasOwnProperty.call(SCHEMAS, namespace)) {
    throw new Error(`Unknown settings namespace: ${String(namespace)}`);
  }
}

/**
 * Reject the promise if `key` is not a setting declared in the namespace schema.
 */
function assertKey(namespace, key) {
  assertNamespace(namespace);
  if (!Object.prototype.hasOwnProperty.call(SCHEMAS[namespace], key)) {
    throw new Error(
      `Unknown settings key: ${String(key)} in namespace ${String(namespace)}`,
    );
  }
}

const settings = {
  /**
   * Resolve to the effective value for `key` in `namespace`: the stored
   * override when present, otherwise the schema default. The original
   * JavaScript type of the value is preserved.
   *
   * Rejects when the namespace or key is not part of a schema.
   */
  async get(namespace, key) {
    assertKey(namespace, key);
    const { value } = await Preferences.get({ key: storageKey(namespace, key) });
    if (value === null || value === undefined) {
      return SCHEMAS[namespace][key];
    }
    return JSON.parse(value);
  },

  /**
   * Persist `value` for `key` in `namespace` through Preferences.
   *
   * Rejects when the namespace or key is not part of a schema.
   */
  async set(namespace, key, value) {
    assertKey(namespace, key);
    await Preferences.set({
      key: storageKey(namespace, key),
      value: JSON.stringify(value),
    });
  },

  /**
   * Remove every stored override that belongs only to `namespace`. After a
   * reset those settings fall back to their defaults and every other namespace
   * is left untouched.
   */
  async reset(namespace) {
    assertNamespace(namespace);
    const prefix = namespacePrefix(namespace);
    const { keys } = await Preferences.keys();
    for (const key of keys) {
      if (key.startsWith(prefix)) {
        await Preferences.remove({ key });
      }
    }
  },

  /**
   * Resolve to an array of the setting keys in `namespace` that currently have
   * a stored override, sorted in ascending alphabetical order.
   */
  async keys(namespace) {
    assertNamespace(namespace);
    const prefix = namespacePrefix(namespace);
    const { keys } = await Preferences.keys();
    const own = [];
    for (const key of keys) {
      if (key.startsWith(prefix)) {
        own.push(key.slice(prefix.length));
      }
    }
    own.sort();
    return own;
  },

  /**
   * Resolve to a plain object mapping every schema key of `namespace` to its
   * effective value (defaults merged with stored overrides).
   */
  async exportNamespace(namespace) {
    assertNamespace(namespace);
    const result = {};
    for (const key of Object.keys(SCHEMAS[namespace])) {
      result[key] = await settings.get(namespace, key);
    }
    return result;
  },

  /**
   * Persist each known setting key found in `data` into `namespace`. Keys that
   * are not present in the namespace schema are ignored.
   */
  async importNamespace(namespace, data) {
    assertNamespace(namespace);
    if (!data || typeof data !== 'object') {
      return;
    }
    const schema = SCHEMAS[namespace];
    for (const key of Object.keys(data)) {
      if (Object.prototype.hasOwnProperty.call(schema, key)) {
        await settings.set(namespace, key, data[key]);
      }
    }
  },
};

// Expose the async settings API on the page.
window.settings = settings;

console.log('Namespaced settings manager ready. window.settings is available.');

// Functional verification of the built settings manager.
// We load the production bundle in a Node environment that polyfills the
// browser globals the Capacitor Preferences web implementation needs.

import { readFileSync } from 'node:fs';
import { pathToFileURL } from 'node:url';

// --- Minimal browser environment shims -------------------------------------

const store = new Map();
const localStorage = {
  getItem(k) {
    return store.has(k) ? store.get(k) : null;
  },
  setItem(k, v) {
    store.set(k, String(v));
  },
  removeItem(k) {
    store.delete(k);
  },
  clear() {
    store.clear();
  },
  key(i) {
    return Array.from(store.keys())[i] ?? null;
  },
  get length() {
    return store.size;
  },
};
Object.defineProperty(localStorage, 'length', { configurable: true });

globalThis.window = globalThis;
globalThis.localStorage = localStorage;
globalThis.document = { title: 'test' };

// --- Load the built bundle and capture window.settings ---------------------

const bundlePath = new URL('../dist/assets/index-lPYbL3UO.js', import.meta.url);
const code = readFileSync(bundlePath, 'utf8');

// The bundle assigns to `window.settings`. Since `window === globalThis`,
// after eval the global `settings` will be populated.
eval(code);

const settings = globalThis.settings;
if (!settings) {
  console.error('FAIL: window.settings is not defined');
  process.exit(1);
}

const assert = (cond, msg) => {
  if (!cond) {
    console.error('FAIL:', msg);
    process.exit(1);
  }
  console.log('ok  -', msg);
};

const assertRejects = async (p, msg) => {
  try {
    await p;
    console.error('FAIL (did not reject):', msg);
    process.exit(1);
  } catch {
    console.log('ok  -', msg);
  }
};

// --- Tests -----------------------------------------------------------------

// Defaults are returned and types preserved.
assert(await settings.get('app', 'theme') === 'light', 'app.theme default = "light" (string)');
assert((await settings.get('app', 'fontSize')) === 14, 'app.fontSize default = 14 (number)');
assert((await settings.get('app', 'notifications')) === true, 'app.notifications default = true (boolean)');
assert((await settings.get('appearance', 'theme')) === 'system', 'appearance.theme default = "system"');
assert((await settings.get('appearance', 'accent')) === 'blue', 'appearance.accent default = "blue"');
assert((await settings.get('editor', 'tabSize')) === 4, 'editor.tabSize default = 4 (number)');
assert((await settings.get('editor', 'wordWrap')) === false, 'editor.wordWrap default = false (boolean)');

// set + get preserves types.
await settings.set('app', 'fontSize', 22);
assert((await settings.get('app', 'fontSize')) === 22, 'set app.fontSize = 22 persists as number');
await settings.set('app', 'notifications', false);
assert((await settings.get('app', 'notifications')) === false, 'set app.notifications = false persists as boolean');
await settings.set('app', 'theme', 'dark');
assert((await settings.get('app', 'theme')) === 'dark', 'set app.theme = "dark" persists as string');

// keys() lists only overridden keys in the namespace, sorted.
let appKeys = await settings.keys('app');
assert(JSON.stringify(appKeys) === JSON.stringify(['fontSize', 'notifications', 'theme']), 'keys(app) = sorted overridden keys');

// Namespace isolation: setting app keys must not make them appear under `appearance`.
const appearanceKeys = await settings.keys('appearance');
assert(JSON.stringify(appearanceKeys) === JSON.stringify([]), 'keys(appearance) = [] (isolation)');

// The critical prefix-isolation check: namespace `app` prefix must not match `appearance`.
await settings.set('appearance', 'theme', 'green');
appKeys = await settings.keys('app');
assert(JSON.stringify(appKeys) === JSON.stringify(['fontSize', 'notifications', 'theme']), 'keys(app) unaffected by appearance override (delimiter-aware)');
const appearanceKeys2 = await settings.keys('appearance');
assert(JSON.stringify(appearanceKeys2) === JSON.stringify(['theme']), 'keys(appearance) = [theme]');

// reset(namepace) removes only that namespace's overrides.
await settings.reset('app');
appKeys = await settings.keys('app');
assert(JSON.stringify(appKeys) === JSON.stringify([]), 'reset(app) clears app overrides');
assert((await settings.get('app', 'fontSize')) === 14, 'after reset(app) fontSize falls back to default 14');
assert((await settings.get('app', 'theme')) === 'light', 'after reset(app) theme falls back to default "light"');
// appearance untouched by reset(app)
assert(JSON.stringify(await settings.keys('appearance')) === JSON.stringify(['theme']), 'reset(app) leaves appearance untouched');
assert((await settings.get('appearance', 'theme')) === 'green', 'appearance.theme still "green" after reset(app)');

// reset(appearance) only affects appearance.
await settings.reset('appearance');
assert(JSON.stringify(await settings.keys('appearance')) === JSON.stringify([]), 'reset(appearance) clears appearance overrides');
assert((await settings.get('appearance', 'theme')) === 'system', 'appearance.theme falls back to "system"');

// exportNamespace returns effective merged object with correct types.
await settings.set('editor', 'tabSize', 8);
const exported = await settings.exportNamespace('editor');
assert(JSON.stringify(exported) === JSON.stringify({ tabSize: 8, wordWrap: false }), 'exportNamespace(editor) merges override + defaults');
assert(typeof exported.tabSize === 'number' && typeof exported.wordWrap === 'boolean', 'exported editor values keep types');

const appExport = await settings.exportNamespace('app');
assert(JSON.stringify(appExport) === JSON.stringify({ theme: 'light', fontSize: 14, notifications: true }), 'exportNamespace(app) = all defaults');

// importNamespace persists known keys, ignores unknown keys.
await settings.importNamespace('app', { fontSize: 30, theme: 'solarized', notARealKey: 'ignored' });
assert((await settings.get('app', 'fontSize')) === 30, 'importNamespace persisted fontSize = 30');
assert((await settings.get('app', 'theme')) === 'solarized', 'importNamespace persisted theme = "solarized"');
assert((await settings.get('app', 'notifications')) === true, 'importNamespace left notifications at default');
const importedKeys = await settings.keys('app');
assert(JSON.stringify(importedKeys) === JSON.stringify(['fontSize', 'theme']), 'importNamespace ignored unknown key (not in keys)');

// Reject for unknown namespace / key.
await assertRejects(settings.get('nope', 'x'), 'get rejects unknown namespace');
await assertRejects(settings.get('app', 'nope'), 'get rejects unknown key');
await assertRejects(settings.set('nope', 'x', 1), 'set rejects unknown namespace');
await assertRejects(settings.set('app', 'nope', 1), 'set rejects unknown key');
await assertRejects(settings.reset('nope'), 'reset rejects unknown namespace');
await assertRejects(settings.keys('nope'), 'keys rejects unknown namespace');
await assertRejects(settings.exportNamespace('nope'), 'exportNamespace rejects unknown namespace');
await assertRejects(settings.importNamespace('nope', {}), 'importNamespace rejects unknown namespace');

// Final isolation sanity: editor untouched by app operations.
assert((await settings.get('editor', 'tabSize')) === 8, 'editor.tabSize still 8 (cross-namespace isolation)');

console.log('\nAll functional checks passed.');

