      return Object.prototype.hasOwnProperty.call(this, k) ? this[k] : null;
    },
  },
  setItem: {
    enumerable: false,
    value(k, v) {
      this[k] = String(v);
    },
  },
  removeItem: {
    enumerable: false,
    value(k) {
      delete this[k];
    },
  },
  clear: {
    enumerable: false,
    value() {
      for (const k of Object.keys(this)) delete this[k];
    },
  },
